// Each site has a cached map (matched) and a handler.
// Smi handler: a number = field index -> 1 load.
// Object handler: { kind } -> a richer recipe -> 4 work units.
function handlerCost(handler) {
  return typeof handler === 'number' ? 1 : 4;
}

const sites = [
  { name: 'p.x',    handler: 0 },                 // in-object field index 0
  { name: 'p.y',    handler: 1 },                 // in-object field index 1
  { name: 'p.size', handler: { kind: 'accessor' } }, // getter
  { name: 'p.tag',  handler: { kind: 'proto' } },    // prototype-chain load
];

let smi = 0, obj = 0, total = 0;
for (const s of sites) {
  const c = handlerCost(s.handler);
  total += c;
  if (typeof s.handler === 'number') smi++; else obj++;
}
console.log('smiHandlers=' + smi + ' objHandlers=' + obj + ' totalCost=' + total);

tasks.starter:
// Two producers build differently-shaped items, both fed to sum().
function fromA(n) { return { value: n, label: 'a' }; }      // {value,label}
function fromB(n) { return { label: 'b', value: n / 2 }; }   // {label,value} -> different shape + float

function sum(items) {
  let acc = 0;
  for (const it of items) acc += it.value; // load IC + BinaryOp IC both see two profiles
  return acc;
}

model.en:
Unify the item shape and the numeric representation at the source, so the single <code>it.value</code> site sees one map and one number type:<br><code>function makeItem(value, label) {
  // one constant key order -> one hidden class for every item
  return { value: Number(value), label };
}
function fromA(n) { return makeItem(n, 'a'); }
function fromB(n) { return makeItem(n / 2, 'b'); }
// sum() unchanged; both producers now yield the same shape, and value is always a Number.</code><br>Key moves: (1) construct every item through one factory with a fixed key order, so <code>fromA</code> and <code>fromB</code> produce the same hidden class and the <code>it.value</code> load IC stays monomorphic; (2) coerce <code>value</code> to <code>Number</code> consistently so the BinaryOp IC settles on one numeric type instead of mixing Smi and Double (which would otherwise generalize and could deopt code specialized on Smi).

model.ru:
