  // один постоянный порядок ключей -> один hidden class для каждого элемента
  return { value: Number(value), label };
}
function fromA(n) { return makeItem(n, 'a'); }
function fromB(n) { return makeItem(n / 2, 'b'); }
// sum() без изменений; оба продюсера теперь дают одну форму, а value всегда Number.</code><br>Ключевые ходы: (1) создавай каждый элемент через одну фабрику с фиксированным порядком ключей, чтобы <code>fromA</code> и <code>fromB</code> давали один hidden class, и load IC у <code>it.value</code> оставался monomorphic; (2) приводи <code>value</code> к <code>Number</code> консистентно, чтобы BinaryOp IC устоялся на одном числовом типе, а не мешал Smi и Double (что иначе обобщилось бы и могло деоптнуть код, специализированный на Smi).

