// caches the discovered property offset per shape-key
const cache = new Map();

function shapeKey(obj) {
  return Object.keys(obj).join(',');     // identify the shape
}

function getProp(obj, name) {
  const key = shapeKey(obj);
  let offset = cache.get(key);
  if (offset === undefined) {
    offset = Object.keys(obj).indexOf(name);
    cache.set(key, offset);              // remember where 'name' lives
  }
  return Object.values(obj)[offset];
}
